#define _GNU_SOURCE
#include <errno.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/socket.h>

int smb_send(int sock, const uint8_t *data, size_t len)
{
    size_t sent = 0;

    if (len != 0 && data == NULL)
        return -1;

    while (sent < len) {
        ssize_t n = send(sock, data + sent, len - sent, MSG_NOSIGNAL);

        if (n < 0) {
            if (errno == EINTR)
                continue;
            return -1;
        }
        if (n == 0)
            return -1;

        sent += (size_t)n;
    }

    return 0;
}

